# Slashblade JS

一个辅助开发者使用 KubeJS 脚本编辑和创建 Slashblade: Resharped 配方，并利用其事件的模组。

# 它能做什么？

以下是一个即用的示例：

```javascript
// priority: 0

/* 服务器端 */

// 当 Slashblade 检查充能状态时：如果未充能，消耗 10 个 ProudSoul 进入充能状态
SlashBladeJSEvents.powerBlade(event => {
    let state = BladeState.of(event.blade)
    let proudsoul = state.proudSoulCount
    if (!event.isPowered() && proudsoul >= 10) {
        state.setProudSoulCount(proudsoul - 10)
        event.setPowered(true)
    }
    event.user.tell("ProudSoul: " + proudsoul) // 通知玩家当前的 ProudSoul 值
})

// 自定义 Slashblade 配方
ServerEvents.recipes(event => {
    event.recipes.slashblade.slashblade_shaped_recipe("slashblade:slashblade", [
        "ABA",
        "CSC",
        "ABC"
    ], {
        "S": SlashBladeIngredient.of(
            SlashBladeRequestDefinition.name("slashblade:fox_black") // 所需的基础剑刃
                .killCount(233) // 击杀数要求
                .proudSoul(114514) // ProudSoul 要求
                .refineCount(10) // 精炼次数要求
                .addEnchantment(SBEnchantmentDefinition.of("minecraft:power", 2)) // 附魔要求
                .build() // 别忘了 .build()
        ),
        "A": "minecraft:golden_apple", // 其他材料（如同原版配方）
        "B": "#forge:bones",
        "C": "minecraft:cake",
    }, "slashblade:fox_white"/* 结果剑刃 ID */)
})

// 创建你的自定义剑刃
ServerEvents.highPriorityData(event => {
    let customBlade = SBSlashBladeDefinition.of("kubejs:test_blade", // 你的剑刃 ID
        SBRenderDefinition.newInstance() // 渲染属性
            .effectColor(2039347) // 剑刃特效颜色（十六进制 RGB 转十进制）
            .standbyRenderType(SBCarryType.DEFAULT) // 鞘中位置
            .modelName("kubejs:model/named/test_blade.obj") // 路径：./kubejs/assets/kubejs/model/named/test_blade.obj
            .textureName("kubejs:model/named/test_blade.png") // 路径：./kubejs/assets/kubejs/model/named/test_blade.png
            .build(), // 别忘了 .build()
        SBPropertiesDefinition.newInstance()
            .maxDamage(666) // 最大耐久度
            .baseAttackModifier(999) // 基础攻击伤害
            .slashArtsType("slashblade:void_slash") // 设置特殊攻击
            .addSpecialEffect("slashblade:wither_edge") // 添加特殊效果
            .defaultSwordType([SBSwordType.FIERCEREDGE, SBSwordType.BEWITCHED]) // 设置剑刃类型
            .build(), // 别忘了 .build()
        [ // 默认附魔
            SBEnchantmentDefinition.of("minecraft:power", 5),
            SBEnchantmentDefinition.of("minecraft:unbreaking", 10)
        ]
    )

    // 注册到游戏中
    event.addJson("kubejs:slashblade/named_blades/test_blade.json", SBSlashBladeDefinition.toJSON(customBlade))
})
```

